import { ReactNode, FC } from 'react';

type AvatarSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | number;
type AvatarShape = 'circle' | 'square';
interface AvatarProps {
    /** 图片地址 */
    src?: string;
    /** 图片加载失败时的备用图 */
    fallback?: string;
    /** 尺寸 */
    size?: AvatarSize;
    /** 形状 */
    shape?: AvatarShape;
    /** 替代文字 (无图片时显示) */
    alt?: string;
    /** 自定义背景色 */
    backgroundColor?: string;
    /** 自定义文字颜色 */
    color?: string;
    /** 点击事件 */
    onClick?: () => void;
    /** 子元素 (自定义内容) */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface AvatarGroupProps {
    /** 最多显示数量 */
    max?: number;
    /** 尺寸 */
    size?: AvatarSize;
    /** 间距 (负值重叠) */
    gap?: number;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

type AvatarComponent = FC<AvatarProps> & {
    Group: FC<AvatarGroupProps>;
};
declare const Avatar: AvatarComponent;
declare const AvatarGroup: FC<AvatarGroupProps>;

export { Avatar, AvatarGroup, Avatar as default };
export type { AvatarGroupProps, AvatarProps, AvatarShape, AvatarSize };
